head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf91000";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf91000.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_13", fn: function(){ return ((dma_reqCkMap.get("delCnt") ?? (() => { throw new Error("unresolved:" + "reqCkMap.delCnt"); })()) > 0); } }, { id: "c_when_18", fn: function(){ return ((dma_map.get("listStatCd") ?? (() => { throw new Error("unresolved:" + "map.listStatCd"); })()) === 'Y'); } }, { id: "c_when_23", fn: function(){ return ((dma_map.get("listStatCd") ?? (() => { throw new Error("unresolved:" + "map.listStatCd"); })()) === 'D'); } }, { id: "c_when_28", fn: function(){ return ((dma_map.get("activYn") ?? (() => { throw new Error("unresolved:" + "map.activYn"); })()) !== 'Y'); } }, { id: "c_when_33", fn: function(){ return ((dma_map.get("activTpCd") ?? (() => { throw new Error("unresolved:" + "map.activTpCd"); })()) !== 'Y'); } }, { id: "c_otherwise_38", fn: function(){ return (!(((dma_reqCkMap.get("delCnt") ?? (() => { throw new Error("unresolved:" + "reqCkMap.delCnt"); })()) > 0) || ((dma_map.get("listStatCd") ?? (() => { throw new Error("unresolved:" + "map.listStatCd"); })()) === 'Y') || ((dma_map.get("listStatCd") ?? (() => { throw new Error("unresolved:" + "map.listStatCd"); })()) === 'D') || ((dma_map.get("activYn") ?? (() => { throw new Error("unresolved:" + "map.activYn"); })()) !== 'Y') || ((dma_map.get("activTpCd") ?? (() => { throw new Error("unresolved:" + "map.activTpCd"); })()) !== 'Y'))); } }, { id: "if_newstkIsuTpContn", fn: function(){ return ((dma_map.get("newstkIsuTpContn") ?? (() => { throw new Error("unresolved:" + "map.newstkIsuTpContn"); })()) !== '000'); } }, { id: "c_when_11", fn: function(){ return (!(String(((dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })())) == null ? '' : ((dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })()))).length === 0) && (dma_COMPANYINFO.get("isurCd") ?? (() => { throw new Error("unresolved:" + "COMPANYINFO.isurCd"); })()) === (dma_map.get("isurCd") ?? (() => { throw new Error("unresolved:" + "map.isurCd"); })())); } }, { id: "if_fornSecuKindNm_txt", fn: function(){ return ((dma_map.get("fornSecuKindNm") ?? (() => { throw new Error("unresolved:" + "map.fornSecuKindNm"); })()) !== '' && (dma_map.get("fornSecuIsuDate") ?? (() => { throw new Error("unresolved:" + "map.fornSecuIsuDate"); })()) !== ''); } }, { id: "if_fornSecuKindNm_2_txt", fn: function(){ return ((dma_map.get("fornSecuKindNm") ?? (() => { throw new Error("unresolved:" + "map.fornSecuKindNm"); })()) !== '' && (dma_map.get("fornSecuIsuDate") ?? (() => { throw new Error("unresolved:" + "map.fornSecuIsuDate"); })()) === ''); } }, { id: "if_fornSecuKindNm_3_txt", fn: function(){ return ((dma_map.get("fornSecuKindNm") ?? (() => { throw new Error("unresolved:" + "map.fornSecuKindNm"); })()) === '' && (dma_map.get("fornSecuIsuDate") ?? (() => { throw new Error("unresolved:" + "map.fornSecuIsuDate"); })()) !== ''); } }, { id: "if_continDeadlineStrtDd_txt", fn: function(){ return ((dma_map.get("continDeadlineStrtDd") ?? (() => { throw new Error("unresolved:" + "map.continDeadlineStrtDd"); })()) !== '' || (dma_map.get("continDeadlineEndDd") ?? (() => { throw new Error("unresolved:" + "map.continDeadlineEndDd"); })()) !== ''); } }, { id: "if_nparvalstkYn_txt", fn: function(){ return ((dma_map.get("nparvalstkYn") ?? (() => { throw new Error("unresolved:" + "map.nparvalstkYn"); })()) === 'Y'); } }, { id: "if_nparvalstkYn_2_txt", fn: function(){ return ((dma_map.get("nparvalstkYn") ?? (() => { throw new Error("unresolved:" + "map.nparvalstkYn"); })()) !== 'Y'); } }, { id: "if_crwfndYn_txt", fn: function(){ return ((dma_map.get("crwfndYn") ?? (() => { throw new Error("unresolved:" + "map.crwfndYn"); })()) ==='Y'); } }, { id: "if_crwfndYn_2_txt", fn: function(){ return ((dma_map.get("crwfndYn") ?? (() => { throw new Error("unresolved:" + "map.crwfndYn"); })()) ==='N'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_type", fn: function () { return String((dma_pageContext.get("stdcdType") ?? "")); } },
        { childId: "ipt_stdCd", fn: function () { return String((dma_pageContext.get("stdCd") ?? "")); } },
        { childId: "__rb0", fn: function () { return "(" + String(dma_map.get("isurCd")) + ") " + String(dma_map.get("comNm")); } },
        { childId: "__rb6", fn: function () { return String(dma_map.get("domFornStkcertTpNm")) + "주권"; } },
        { childId: "__rb9", fn: function () { return String(dma_map.get("fornSecuKindNm")) + "&nbsp;&nbsp;(발행일:" + String(dma_map.get("fornSecuIsuDate")) + ")"; } },
        { childId: "__rb11", fn: function () { return "발행일:" + String(dma_map.get("fornSecuIsuDate")); } },
        { childId: "__rb12", fn: function () { return String(dma_map.get("continDeadlineStrtDd")) + " ~ " + String(dma_map.get("continDeadlineEndDd")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_goModify_onclick
 * @description btn_goModify 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_goModify_onclick = async function(e){
    try {
        await scwin.go_modify()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf91000.btn_goModify_onclick' }); }
};

/**
 * @method
 * @name btn_goDelete_onclick
 * @description btn_goDelete 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_goDelete_onclick = function(e){
    try {
        scwin.go_delete()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf91000.btn_goDelete_onclick' }); }
};

/**
 * @method
 * @name btn_print_onclick
 * @description btn_print 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_print_onclick = async function(e){
    try {
        await scwin.print()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf91000.btn_print_onclick' }); }
};

/**
 * @method
 * @name btn_self_onclick
 * @description btn_self 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf91000.btn_self_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_go_modify
 * @description go modify 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_go_modify = async function () {
    const sbmOptions = {
        id: "tx_go_modify",
        method: "post",
        action: "/stdcd/stdcdModify.do?method=stdcdModify",
        ref: "dma_goModifyReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_print
 * @description print 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_print = async function () {
    try { return await $c.data.downFile("/common/newPrint.do", "", ($c.util.getComponent("dma_printReq") ? $c.util.getComponent("dma_printReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name open_password
 * @description open password 처리
 * @param {*} ipt_type ipt_type
 * @returns {void}
 * @hidden N
 */
scwin.open_password = function (ipt_type) {
    const form = (document.JLDINF91000 || { elements: [] });
    $c.util.getComponent('ipt_modDelCd').setValue(ipt_type);
    fn_passwordWin(form);
};

/**
 * @method
 * @name go_modify
 * @description go modify 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.go_modify = async function () {
    const form = (document.JLDINF91000 || { elements: [] });
    form.action = "/stdcd/stdcdModify.do?method=stdcdModify";
    form.target = "_top";
    await scwin.tx_go_modify();
};

/**
 * @method
 * @name go_delete
 * @description go delete 처리
 * @returns {void}
 * @hidden N
 */
scwin.go_delete = function () {
    const form = (document.JLDINF91000 || { elements: [] });
    fn_stdCdDelWin(form);
    $c.win.closePopup();
};

/**
 * @method
 * @name print
 * @description print 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.print = async function () {
    if (!await $c.win.confirm("주권 상세정보를 출력하시겠습니까?")) {
        return false;
    } else {
        const std_cd = $c.util.getComponent("dma_goModifyReq").get("stdCd");
        $.ajax({ type: "POST", async: false, url: "/srch/srch.do?method=srchReportCommonAjax&serviceName=srchReport2&std_cd=" + std_cd, data: {  }, success: async function(data) {
                    const result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                    const form = (document.newReportForm || { elements: [] });
                    for (key in result) {
                        if (form[camelize(key)]) {
                            form[camelize(key)].value = result[key];
                        }
                    }
                    await scwin.tx_fn_print();
                }, error: async function(request, status, error) {
                    await $c.win.alert("장애발생.");
                    return;
                }, complete: function() {

                } });
    }
};

/**
 * @method
 * @name printOld
 * @description print Old 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.printOld = async function () {
    if (!await $c.win.confirm("주권 상세정보를 출력하시겠습니까?")) {
        return false;
    } else {
        const formName = (document.JLDINF91000 || { elements: [] });
        const std_cd = $c.util.getComponent("dma_goModifyReq").get("stdCd");
        const rexName = "JLDINF91000";
        const dataType = "XML";
        const dataLocation = "/srch/srch.do?method=srchReport2&std_cd=" + std_cd;
        const dataXPath = "main/rpt1";
        const mktGubun = "1";
        fn_PrintPreView_DB(rexName, dataType, dataLocation, dataXPath);
    }
};
